SELECT o.first_shipped_on, o.window_start, o.window_end, o.loads, o.loaded_turns, o.judged_turns, o.corrected_turns, o.base_judged_turns, o.base_corrected_turns, o.retired_at, o.retired_reason FROM memory.skill_live_outcomes o WHERE o.project_id = (SELECT min(id) FROM projects.projects WHERE project_path = '/tmp/perf-project') AND o.folder = 'topic-7' AND o.retired_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM memory.skill_drafts d WHERE d.project_id = o.project_id AND d.folder = o.folder AND d.created_at > o.retired_at AND d.status <> 'rejected') ORDER BY o.first_shipped_on DESC LIMIT 1
